"""Detailed shipped Service descriptions and recognition of previous bridge defaults."""

from collections.abc import Mapping

# Preserve the original short defaults to recognize uncustomized bridge descriptions.
OVERVIEWS: dict[str, str] = {
    "calendar": "Keep your personal appointments and dated reminders in Galaris without an external account. Each reminder creates a tracked Task. Use Goals for durable outcome-driven work and their own scheduled reviews; do not duplicate a Goal cycle as a calendar reminder.",
    "service": "Discover your available tools. Administer agent connections within the personal, team or all services.management_scope delegated on this connection. Shared Service definitions and global settings require all; exact function permissions still apply. Test HTTP/SSE MCP without saving or invoking remote functions; secrets remain server-side. ServiceAdmin and other administrative delegations remain human-only.",
    "agent": "Discover agents and their roles. Administer agents, avatars, teams, connections and existing Harness selections within your human manager's current privileges and management scope.",
    "galaris": "Coordinate teams, delegate Tasks, and inspect their progress. Resource access remains subject to ownership and sharing rights; administration and conversation controls belong to separate Services.",
    "document": "Inspect and manage sharing of editorial HTML Documents. Document access is independent of personal agent memory.",
    "memory": "Retain private durable facts, decisions and attributed conversation summaries for future work, or permanently forget an eligible memory. Reading and searching use the File sharing Service.",
    "file_sharing": "Discover and manipulate authorized resources through canonical URIs: files, documents, memories, attachments and Galaris business records. Read, search, create, edit or transfer content where the provider supports it. This service grants neither access to other agents’ private resources nor an implicit local filesystem.",
    "goal": "Create, track and manage long-running Goals. Every agent starts with an active connection and personal scope; team and global scope require explicit delegation.",
    "skills": "Use authorized generic and private personal skill packages. The single Skills Service has server-owned usage, personal, team and all scopes. Personal permits managing only your own packages; team covers agents sharing any active team; all permits explicit global administration and generic distribution. Maintain files at galaris://skill/personnal/<your-agent-id>/<code>/ through File Sharing. A personal package cannot be shared or assigned. Ownership release is explicit, revisioned and replay-safe; the resulting generic starts disabled for everyone. Only a global human manager can delegate scope through services.management_scope on the Skills connection. System package files are read-only.",
    "process": "Create and manage native business processes, run assigned workflows, and inspect authorized runs. Each agent starts with personal scope. Team and global management require explicit delegation.",
    "topic": "Administer the shared thematic organization of Tasks, messages, conversation rounds, memories and documents. Create and edit Topics, inspect their contents, reassign items and merge or split Topics.",
    "search": "Search the public web through the configured local SearXNG service and return results for the agent to assess. Reading full pages and interacting with sites use the Browser Service.",
    "browser": "Open and navigate web pages in an isolated browser session. Read accessible content, take screenshots, click controls, type, scroll and close the session. Actions on signed-in sites use that session’s access.",
    "chat": "Provide the native Galaris channel, resolve pending choices, present authorized repositories, manage voice calls and inspect permitted conversation turns.",
    "console": "Execute commands and manage long-running processes on the configured SSH account: start, poll, send input and stop. Its home directory becomes the console:// resource provider for File sharing. Access is limited by that account and the configured host key.",
    "mail": "Search and read IMAP mailboxes, move messages, change flags and trash mail. Send, reply and forward through SMTP with attachments and an AI-agent disclosure signature. Optional human approval and size limits follow the connection settings.",
    "caldav": "Read configured personal or delegated iCalendar feeds, inspect events, check availability and find free slots. Create, update and delete events on writable HTTPS calendars; timezone and working hours follow the connection settings.",
    "n8n": "Connect an external n8n workflow engine to Galaris Processes. Assigned workflows run asynchronously with durable status, inputs, resource references and results. Process execution and administration are exposed through their respective Services.",
    "image": "Generate and edit images with configured image models, or describe an existing image. Inputs and outputs use authorized resource URIs; availability depends on the configured model capabilities.",
    "audio": "Transcribe an audio or video resource, or retrieve available public YouTube captions. Pass the canonical source URI directly; supported formats, provider availability and configured size limits determine processing.",
    "multimedia": "Analyze audio and video and generate sound effects, music or video using configured specialist models. Supply canonical resource URIs; only operations supported by the agent’s configured providers are exposed.",
    "messenger": "Connect an agent to a messaging service to receive and send messages, inspect authorized conversations and exchange attachments. Recipients and rooms remain subject to the connection’s access rules.",
    "matrix": "Receive and send Matrix messages, inspect authorized rooms and exchange attachments through a configured agent account. Homeserver, credentials and supported room capabilities determine access; compatible calls use the Voice Service.",
    "telegram": "Connect a Telegram bot to receive messages and send replies or attachments. Bot credentials and allowed users and chats govern access; group mention rules determine when the agent responds.",
    "whatsapp": "Connect WhatsApp Cloud messaging to an agent through Meta credentials and webhooks. Exchange supported messages and media with allowed contacts; proactive delivery follows the configured approved template and provider constraints.",
    "one_bot": "Connect a OneBot v11 adapter to Galaris for private and group messages and supported attachments. The adapter’s account, platform and authenticated WebSocket connection determine the available messaging capabilities.",
    "nextcloud_talk": "Use a configured Nextcloud account for Talk conversations and supported attachments. Access follows room membership and server capabilities; compatible real-time calls use the Voice Service.",
    "nextcloud": "Access the configured Nextcloud account’s files through WebDAV. Browse, read, create, edit and transfer authorized resources using File sharing; account permissions apply to each operation.",
    "affine": "Access file blobs in authorized AFFiNE workspaces using the configured account. Transfer resources through File sharing with an explicit workspace destination; this connection does not edit AFFiNE document blocks.",
}

_DETAILS: dict[str, str] = {
    "calendar": "## Capabilities\n\nCreate, move and remove personal appointments, inspect availability and set dated reminders. Set reminder_minutes_before=0 for a reminder at the event start. Each due reminder admits one tracked Task.\n\n## Boundary with Goals\n\nUse Goals for an ongoing result, iterative work and scheduled progress reviews. Do not mirror a Goal cycle in the agenda. A Goal-related appointment is appropriate only for a distinct real-world commitment. Connected calendars are optional and retain their own function permissions.",
    "service": "## Capabilities\n\nDiscover available tools with services_list. With delegation, administer custom Services, inherited settings, optional agent connections and function permissions. Inspect impact and use version preconditions for mutations. Test an HTTP/SSE candidate or resolved connection before activation.\n\n## Requirements and limits\n\nActive by default with usage scope. The local services.management_scope delegates personal, team or all administration, constrained by each function grant. Shared definitions and global settings require all. Mandatory services, integrated definitions and administrative delegations remain protected. Secrets use existing configuration or agent-bound human-prepared references; stdio execution is outside this capability.",
    "agent": "## Capabilities\n\nCreate, update and soft-delete agents; manage shared titles, groups and team memberships; configure optional connections, masked parameters and local function permissions; select and supervise existing Harnesses. Generate or regenerate another agent's avatar with agent_avatar_generate and explicit appearance/style instructions, including realistic human portraits, when your effective image model is configured. No separate Image Service is required.\n\n## Access\n\nActive by default with usage scope. Scope is bounded by services.management_scope (usage, team, all), excludes self-modification, and follows your active human manager's current privileges. Global management extends target scope but does not replace domain rights. Shared reference mutations require global management. Only humans can change administrative delegation. System Services remain protected. The usage scope exposes agent_list and agent_get. No skills, provider provisioning or task termination functions are included.\n\n## Portrait registration\n\nGeneration waits for registration and returns registered=true on success; it does not create a Process. A changed target profile/avatar or revoked delegation prevents late publication and preserves the current avatar.",
    "galaris": "## Capabilities\n\n- **Coordination:** use team_list and team_members to find shared teams and their active human/agent members.\n- **Tasks:** launch work for another agent, inspect its state and result, or stop an eligible task.\n\n## When to use it\n\nUse this service to distribute work among specialists and retain durable progress. **Example:** delegate research, collect the result.\n\n## Requirements and limits\n\nMandatory system service. Delegation cannot target the calling agent itself. Task access remains controlled; broader administrative operations require their dedicated Services.",
    "document": "## Capabilities\n\nInspect Document permissions and discover recipients, then grant or revoke access to an owned Document. Manage Document access and present content in Chat.\n\n## Access\n\nUse document_sharing for recipient IDs and lock_version before document_share. Selected Document operations use File Sharing and apply Document scope, rights and revision checks. Read and edit general document:// content through File sharing. A URI or link grants no access. Personal memories cannot be shared.",
    "memory": "## Capabilities\n\n- **Remember:** retain a fact, preference or decision useful for future work as HTML content; its display label is derived from that content.\n- **Summarize:** condense a conversation into attributed facts, decisions, commitments and open questions instead of retaining the entire transcript.\n- **Forget:** permanently delete a memory the agent is entitled to forget, including its revisions.\n\n## When to use it\n\nUse it when information should survive a conversation and remain retrievable. **Example:** retain a confirmed project decision for future work. Use a working document for an evolving report or content to share with a team.\n\n## Requirements and limits\n\nMandatory system service. Standalone memories are private to their agent and have no authored title or independent sharing. Documents own titles, full content and sharing; optional shared summaries and their history belong to Document. Search uses the full document and its synthesis, returns one result per pair and applies current document permissions. Reading, searching and editing documents use File sharing. Sharing requires owner rights; mentioning or linking an item grants no access. Conversation synthesis is limited to 200 messages and 32,000 characters and needs an available model. Acquisition may store, merge or reject a memory.",
    "file_sharing": "## Capabilities\n\n- **Discover:** identify accessible spaces, browse collections and search by name or supported search modes.\n- **Read and inspect:** obtain metadata or read content in bounded portions from its canonical URI.\n- **Write:** create working documents or files, replace content, append text and make targeted edits.\n- **Transfer:** copy across spaces, move or delete where the storage service supports it, and manage document attachments.\n\n## When to use it\n\nUse it as the common entry point to content wherever it is stored. **Example:** read a document, enrich its existing version and copy an attachment to Nextcloud without moving the whole file through the conversation.\n\n## Requirements and limits\n\nMandatory system service. Each space retains its permissions and capabilities: Galaris business records are generally read-only, while Document owns editorial HTML at document://; Dataset owns independent JSON resources at data:// with their own revisions and sharing. Create Datasets directly at data:// with complete JSON in content. Verified old Document aliases remain readable. External storage requires its own connection; local space exists only with an available Console. Each owning domain enforces resource access and sharing.",
    "goal": "## Capabilities\n\nCreate and update durable goals, track progress, start cycles and manage the lifecycle. The connection starts active with personal scope. An authorized person can delegate team or global scope. Changes use the current revision to prevent concurrent overwrites.",
    "skills": "Use authorized generic and private personal skill packages. The single Skills Service has server-owned usage, personal, team and all scopes. Personal permits managing only your own packages; team covers agents sharing any active team; all permits explicit global administration and generic distribution. Maintain files at galaris://skill/personnal/<your-agent-id>/<code>/ through File Sharing. A personal package cannot be shared or assigned. Ownership release is explicit, revisioned and replay-safe; the resulting generic starts disabled for everyone. Only a global human manager can delegate scope through services.management_scope on the Skills connection. System package files are read-only.",
    "process": "## Capabilities\n\nCreate and edit native definitions, start assigned workflows, inspect progress and manage run history. Existing sharing and function permissions apply.\n\n## Management scope\n\nThe connection starts active with personal scope. An authorized person can delegate team or global scope. Discovering and synchronizing engines or binding external workflows requires global scope.",
    "topic": "## Capabilities\n\n- **Build shared organization:** create topics with a title, description and keywords, then update their metadata.\n- **Explore a topic:** inspect its record and list its assigned objects.\n- **Reorganize:** move items between topics, merge topics or split one by selecting the items to transfer.\n\n## When to use it\n\nUse it to keep activities and agents organized consistently. **Example:** group a project's tasks, exchanges and documents, then separate a subproject that has become independent.\n\n## Requirements and limits\n\nOptional administrative Service. Topics are shared across the instance, so reorganization has a collective scope. Updates check the current revision. Merging or moving changes organization without granting new content access rights.",
    "search": "## Capabilities\n\n- **Find sources:** query the configured SearXNG engine and receive results with titles, links and excerpts.\n- **Explore a subject:** vary search terms to identify relevant documentation, announcements or websites.\n- **Prepare deeper reading:** obtain addresses to open with Browser.\n\n## When to use it\n\nUse it at the start of research or to find a specific public source. **Example:** locate a software product's official documentation, then read the selected page to verify a detail.\n\n## Requirements and limits\n\nOptional service, active by default. SearXNG must be available. Results and excerpts are leads; they guarantee neither accuracy nor freshness. This Service does not replace reading complete pages or provide access to private website areas.",
    "browser": "## Capabilities\n\n- **Navigate:** open pages, follow addresses, go back and close sessions.\n- **Understand interfaces:** read accessible page content and identify interactive elements.\n- **Act:** click, fill fields, submit input, use the keyboard and scroll.\n- **Inspect appearance:** capture screenshots and change viewport size to examine an interface.\n\n## When to use it\n\nUse it when complete pages must be read or websites require interaction. **Example:** read documentation, fill an authorized form or inspect a page's mobile layout.\n\n## Requirements and limits\n\nOptional Service, inactive by default. Sessions are isolated and tied to their work; they do not automatically reuse your personal browser. Actions use the account rights in that session. Enabling the Service does not itself authorize publishing, purchasing or sending data.",
    "chat": "## Capabilities\n\n- Exchange messages and attachments through the Galaris channel.\n- Resolve pending choices and present authorized repositories.\n\n## Access\n\nThe system connection stays active. Enable or disable the internal channel per agent independently of external messaging. Individual functions require the applicable permissions.",
    "console": "## Capabilities\n\n- **Check the environment:** inspect SSH connectivity, permissions, working directory and execution capabilities.\n- **Execute:** run commands or scripts and read output, exit codes and errors.\n- **Track long work:** start a process, poll new output, send input or stop it.\n- **Work with files:** expose the remote home directory to File sharing through `console://`.\n\n## When to use it\n\nUse it for development, calculations, conversions or programmatic file analysis. **Example:** run a script on data, monitor its progress and retrieve the resulting artifact.\n\n## Requirements and limits\n\nRequires a configured SSH server, account and host key; the native console requires a harness with SSH Console support. Remote account permissions apply. Some process-control commands require the Galaris execution helper. Installed software and network access depend on the server; privileged access is never implicit.",
    "mail": "## Capabilities\n\n- **Read mail:** check connectivity, list folders, search messages and inspect bodies and attachments.\n- **Organize:** change flags, move messages or send them to Trash.\n- **Correspond:** send new mail, reply or forward with authorized attachments.\n- **Control delivery:** use the configured sender identity, an AI-agent disclosure signature and optional human approval.\n\n## When to use it\n\nUse it to process an inbox or maintain correspondence. **Example:** find an exchange, read its attachment and send an approved reply with the deliverable.\n\n## Requirements and limits\n\nRequires IMAP/SMTP settings and account credentials. Deliveries use a retry key to prevent duplicates; sizes and timeouts are bounded. Incoming messages are external content. Enabling Mail does not replace human instructions about recipients and authorized sends.",
    "caldav": "## Capabilities\n\n- **Read:** list configured calendars and inspect events within a period.\n- **Check availability:** detect conflicts for a proposed time and find free slots of a given duration.\n- **Plan:** respect configured timezone, working hours and search increments.\n- **Update calendars:** create, update or delete events on writable calendars.\n\n## When to use it\n\nUse it to prepare appointments and organize time using personal or delegated calendars. **Example:** find a conflict-free one-hour slot and create the event in the intended calendar.\n\n## Requirements and limits\n\niCalendar sources must be configured. Read-only calendars cannot be modified; writes need a compatible HTTPS calendar. Dates and timezones should be explicit. Creating an event does not prove that invitations were sent or accepted by every participant.",
    "n8n": "## Capabilities\n\n- **Connect systems:** use an external n8n engine's workflows as Galaris business processes.\n- **Supply inputs:** pass parameters and file references to assigned workflows.\n- **Track execution:** retain durable status, results and errors even when work finishes later.\n- **Separate roles:** manage definitions with Process administration and run assigned workflows through Galaris or Conversation.\n\n## When to use it\n\nUse it when business operations should chain external integrations in an existing workflow. **Example:** launch document processing or synchronization between services, then collect the result when the process finishes.\n\n## Requirements and limits\n\nRequires a configured n8n engine and workflows that are exposed and assigned. This Service does not provide an n8n workflow editor within Galaris or automatically create external credentials. Engine permissions and settings remain necessary.",
    "image": (
        "## Capabilities\n\n- **Create:** generate an image from a brief using supported dimensions and destinations.\n"
        "- **Edit or compose:** use existing images as references for a change or a new composition.\n"
        "- **Understand:** describe an existing image and answer a visual-analysis request.\n"
        "- **Reuse analysis:** retain the description in Memory, associated with the document attachment or resource.\n"
        "- **Convert PDF pages:** image_from_pdf renders a selected physical page to a faithful PNG without an AI model. "
        "Use its returned URI when a Process requires an image and the human supplied a PDF.\n\n"
        "## When to use it\n\nUse it to produce illustrations or work with visual information. "
        "Examples: adapt an illustration, describe a received image, or prepare an image from a PDF for a Process.\n\n"
        "## Requirements and limits\n\nOptional Service. Generation and analysis require compatible models; PDF conversion does not. "
        "Inputs must be accessible and destinations writable. PDF rendering exports one selected page, "
        "preserves the source and never overwrites a destination. Generation can vary and analysis can be imperfect; "
        "verify important details. Analysis fails if its description cannot be saved, so it has a durable effect beyond reading."
    ),
    "audio": "## Capabilities\n\n- **Transcribe speech:** process audio files or extract speech from video into text.\n- **Use YouTube:** retrieve available public captions without downloading the entire video.\n- **Handle long content:** retain the transcript and produce a synthesis when processing exceeds the supported threshold.\n- **Choose output:** use supported language and destination options, then reuse the resulting text files.\n\n## When to use it\n\nUse it for interviews, recorded meetings or talks. **Example:** transcribe a recording, read its synthesis and prepare meeting notes in a working document.\n\n## Requirements and limits\n\nOptional Service. Audio/video files require a configured transcription model; YouTube requires accessible captions. Private, restricted or captionless sources may be rejected. This Service handles speech; sound, music and video-scene analysis belongs to Multimedia.",
    "multimedia": "## Capabilities\n\n- **Analyze audio:** describe sound events, ambience, instruments or music.\n- **Analyze video:** examine scenes and actions in a video resource.\n- **Create media:** generate sound effects, music or video using options supported by available models.\n- **Track production:** receive a generation ID, then inspect progress and the resulting file URIs.\n\n## When to use it\n\nUse it for creative work or analysis beyond speech transcription. **Example:** describe a video sequence, generate ambience or create a short video from a brief.\n\n## Requirements and limits\n\nOptional Service requiring specialist models; only supported operations are exposed. Generation is asynchronous: a started generation is not yet an available media file. Destinations must be writable. Use Audio transcription for spoken words and Image for still images.",
    "messenger": "## Capabilities\n\n- **Receive and reply:** route connected-service messages to the agent and publish its responses.\n- **Recover context:** list accessible rooms and inspect history where the service supports it.\n- **Contact and deliver:** search recipients when supported, send direct messages or deliver attachments.\n- **Retain references:** use incoming media URIs with other Services without requiring a preliminary local copy.\n\n## When to use it\n\nUse it to make an agent reachable in a communication channel your team already uses. **Example:** receive a question with a file, process it and deliver the result to the intended recipient.\n\n## Requirements and limits\n\nThis describes the shared messaging capability; each bridge declares its own supported functions. A connection and agent identity must be configured. Rooms, recipients and media remain subject to service rules. Delivering an external file and sharing a Galaris document are separate operations.",
    "matrix": "## Capabilities\n\n- **Join exchanges:** receive and send messages using the agent's Matrix account.\n- **Read context:** access authorized rooms and their history within account permissions.\n- **Exchange resources:** receive and deliver supported attachment types, then use file and media Services to process them.\n- **Configure interaction:** restrict users or rooms, require group mentions and control invitation acceptance according to settings.\n\n## When to use it\n\nUse it to integrate an agent into a team working on Matrix. **Example:** mention the bot in a project room, provide an attachment and receive a response in the same room.\n\n## Requirements and limits\n\nRequires a configured homeserver and Matrix identity. Room membership does not remove connection-specific restrictions. Encryption and calling depend on supported capabilities; automatic invitation acceptance covers authorized unencrypted invitations. Compatible calls use Conversation.",
    "telegram": "## Capabilities\n\n- **Talk to a bot:** receive requests and publish agent responses in authorized chats.\n- **Work with media:** exchange supported attachments and media messages, whose URIs can be passed to other Services.\n- **Set scope:** configure allowed users and chats, plus group mention or direct-reply requirements.\n\n## When to use it\n\nUse it to offer convenient access to an agent through Telegram. **Example:** send a document to the bot, request analysis and receive the response in the same chat.\n\n## Requirements and limits\n\nRequires a created bot and configured token. Capabilities follow the Bot API and the bot's effective permissions, not those of a full user account. Knowing an identifier does not guarantee the bot can contact its owner. Groups and contacts must comply with connection rules.",
    "whatsapp": "## Capabilities\n\n- **Receive requests:** integrate incoming messages delivered by WhatsApp Cloud webhooks.\n- **Reply and deliver:** send supported messages and media using the configured WhatsApp Business identity.\n- **Control contacts:** apply allowed phone numbers and Meta account settings.\n- **Prepare proactive messages:** use an approved template and language when the sending context requires them.\n\n## When to use it\n\nUse it to make an agent reachable through WhatsApp Business. **Example:** receive a request from an allowed contact and return the requested information or document.\n\n## Requirements and limits\n\nRequires Meta configuration, a Business number, credentials and webhooks. Provider conversation and template rules still apply; proactive delivery may need an approved template. This bridge does not automatically connect personal WhatsApp accounts or guarantee support for every media type.",
    "one_bot": "## Capabilities\n\n- **Adapt a platform:** connect a OneBot v11-compatible service to Galaris conversations.\n- **Exchange messages:** receive and send private or group messages supported by the adapter.\n- **Transfer media:** process attachments accepted by the platform and retain references for other Services.\n\n## When to use it\n\nUse it when your messaging platform provides a OneBot v11 adapter. **Example:** connect an agent account to a community and handle requests in its existing groups.\n\n## Requirements and limits\n\nRequires a working adapter, platform account and a configured WebSocket connection authenticated according to the deployment. Capabilities vary by adapter; the shared protocol does not guarantee every platform feature. This Service provides messaging, not general administration of the external account.",
    "nextcloud_talk": "## Capabilities\n\n- **Participate in rooms:** receive requests and send responses through the agent's Nextcloud account.\n- **Recover exchanges:** access conversations and history available to that account.\n- **Exchange attachments:** process supported media and their references through File sharing.\n- **Use voice:** call through Chat when supported by the server and provider.\n\n## When to use it\n\nUse it to integrate an agent into collaboration already hosted on Nextcloud. **Example:** discuss a report in a Talk room, provide an attachment and receive the analysis there.\n\n## Requirements and limits\n\nRequires a Nextcloud server and an account authorized in the relevant rooms. Capabilities depend on Talk and server configuration. Talk messaging and general WebDAV file access are separate capabilities; having one does not automatically grant all rights to the other.",
    "nextcloud": "## Capabilities\n\n- **Browse files:** list folders and inspect metadata for resources accessible to the account.\n- **Read and write:** retrieve files, upload new ones and edit supported content.\n- **Organize:** copy, move or delete resources when account permissions allow it.\n- **Transfer across services:** use File sharing to import attachments or export deliverables to Nextcloud.\n\n## When to use it\n\nUse it as an external document space shared with your team's usual tools. **Example:** retrieve a dataset from Nextcloud, process it and upload results to the agreed folder.\n\n## Requirements and limits\n\nRequires server WebDAV access and account credentials. Nextcloud permissions apply to each operation. Commands come from File sharing; this bridge does not provide access to every Nextcloud application or replace a Talk connection.",
    "affine": "## Capabilities\n\n- **Upload files:** transfer binary content to an authorized AFFiNE workspace.\n- **Retrieve resources:** download known files using their reference and workspace.\n- **Exchange across storage:** use File sharing to transfer resources between AFFiNE and another accessible space.\n\n## When to use it\n\nUse it when files produced or consumed by an agent belong in an existing AFFiNE workspace. **Example:** upload an image or binary document to the intended workspace and retain the returned reference.\n\n## Requirements and limits\n\nRequires a configured account and an explicit, authorized workspace. The bridge handles binary files, not AFFiNE document blocks, databases or layouts. Uploading a file does not mean it was inserted into a page or shared with new users.",
}

OVERVIEWS.update({
    "galaris": "Search official product documentation and inspect model calls and incidents within a delegated scope.",
    "contact": "Find and manage the contacts available to the agent.",
    "task": "Delegate, track and control Tasks, including work requested in a conversation.",
})
_DETAILS["galaris"] = "## Access\n\nMandatory system Service. Each function is authorized independently."
_DETAILS["contact"] = (
    "## Capabilities\n\nList, inspect, create and update contacts.\n\n"
    "## Access\n\nThe Contact connection defaults to personal scope. An authorized human can delegate team "
    "or global scope via services.management_scope. Each function retains its own permission. "
    "Use owner_agent_id to filter a list or choose the address book for a new contact."
)
_DETAILS["task"] = (
    "## Capabilities\n\nDelegate work to a colleague, follow progress, update milestones or stop an eligible Task. "
    "In conversation, submit or amend work and pause, resume or retry Tasks.\n\n"
    "## Access\n\nThe Tasks connection defaults to personal scope. Team or global scope extends access "
    "to other agents' Tasks and enables delegation within that scope. Each function has its own permission."
)
_DETAILS["document"] += (
    "\n\n## Delegated scope\n\nThe Documents connection defaults to personal scope. Its tools check "
    "the owning agent's scope and require the document's read or write permission. "
    "A delegated editor can manage sharing on an in-scope agent's document."
)
OVERVIEWS["browser"] += " Search the public web through the configured SearXNG provider."
_DETAILS["browser"] += "\n\nUse search_web to find source URLs before opening selected pages. Search and browsing each have their own tool permissions."
OVERVIEWS["multimedia"] = "Analyze and generate media, transcribe speech and extract PDF pages as images."
_DETAILS["multimedia"] = (
    "## Capabilities\n\nTranscribe audio or video and retrieve available public YouTube captions. Generate or read images, "
    "convert PDF pages into images, analyze audio and video, or generate sound, music and video. "
    "Tools use authorized resource URIs and the configured specialist model when required."
)
_DETAILS["galaris"] += (
    "\n\n## Product knowledge\n\nEnable documentation_catalog and documentation_search to let any agent explain Galaris. "
    "Read sources with File sharing below galaris://documentation/. The galaris-knowledge system skill "
    "is available to authorized agents under their skill assignment policy. Documentation includes current guides, "
    "architecture decisions and explicitly prospective plans for the shipped version. Semantic search falls back "
    "to text search when the vector model or its index is unavailable.\n\n"
    "The catalogue permission controls direct source URI access. Both documentation tools are eligible for Chat.\n\n"
    "## Execution diagnostics\n\nModel-call and incident inspection require a function grant and a delegated "
    "personal, team or global scope on Services. "
    "Failure journal: use incidents_list to filter and paginate LLM/tool failures, then incident_get "
    "for one sanitized trace. Date filters are inclusive and require timezone offsets. Personal/team "
    "scopes restrict incidents to their agents; all scope additionally exposes unowned incidents "
    "and shared pattern diagnoses, remediation, fix references and counts. These tools never resolve "
    "or purge incidents."
)
_DETAILS["chat"] += (
    "\n\n## Voice and execution diagnostics\n\nWith a compatible calling provider and function grants, start, "
    "list or end voice calls. Text-round and voice-turn inspection requires separate function grants and the "
    "delegated scope on Services. The transferred tools are disabled by default for new agents."
)

OVERVIEWS["lab"] = "Operate all eleven AI Labs, compare experiments and diagnose Tasks."
_DETAILS["lab"] = (
    "## Capabilities\n\nCreate and clone datasets, capture cases, generate synthetic drafts, "
    "edit experimental prompts, run repeated benchmarks, cancel/resume, rejudge, compare and review results. "
    "Long analyses and generations return durable Process references.\n\n"
    "## Access\n\nDisabled by default. Enable this connection and assign the galaris-lab skill to an "
    "experimenting agent. Real-source capture and Task diagnostics additionally require the "
    "relevant inspection functions on Galaris and Chat. Agent assessments are attributed separately "
    "from human reviews. Experimental edits do not promote production settings."
)

_DETAILS["file_sharing"] += (
    "\n\n## PDF export\n\nfile_to_pdf converts supported raster images, Office/OpenDocument, RTF, "
    "HTML/SVG/Markdown and text resources into a validated PDF, without a model or Console. "
    "Pass the source URI and an explicit writable destination. The original stays intact and existing "
    "destinations are never overwritten. Multi-frame images retain all frames, up to 100; Office exports "
    "follow printable layout. HTML is static without scripts or external resources. Return the created "
    "application/pdf URI for Process inputs or requested delivery, and report conversion warnings. "
    "Unsupported formats and corrupt files fail explicitly."
)

DESCRIPTIONS: dict[str, str] = {
    code: f"## Purpose\n\n{overview}\n\n{_DETAILS[code]}" for code, overview in OVERVIEWS.items()
}


def bridge_description(
    *configs: Mapping[str, object] | None,
    overview_only: bool = False,
) -> str:
    """Describe configured capabilities, or identify their previous concise default."""
    catalog = OVERVIEWS if overview_only else DESCRIPTIONS
    descriptions: list[str] = []
    for config in configs:
        service = str((config or {}).get("service") or "")
        if service == "internal":
            service = "chat"
        description = catalog.get(service, "")
        if description and description not in descriptions:
            descriptions.append(description)
    return "\n\n".join(descriptions)
